"""tr — prophets_c."""

T = {
"prophets_151": ("Âdem ve eşinin cennette yaklaşması yasaklanan şey neydi?", ["Bir ağaç", "Bir nehir", "Bir kapı", "Bir dağ"], "Allah onlara diledikleri gibi yemelerine izin verdi; yalnız tek bir ağaca yaklaşmalarını yasakladı."),
"prophets_152": ("Kur'an'a göre Âdem, hatasından sonra Rabbinden ne aldı?", ["Kelimeler (tövbe sözleri) aldı ve Allah tövbesini kabul etti", "Servet", "Bir krallık", "Bir kitap"], "«Âdem, Rabbinden birtakım kelimeler aldı; Allah da tövbesini kabul etti»."),
"prophets_153": ("Kur'an, yaratılışı bakımından İsa'yı kime benzetir?", ["Topraktan yaratılan Âdem'e", "Nuh'a", "İbrahim'e", "Yahya'ya"], "«Allah katında İsa'nın durumu Âdem'in durumu gibidir: onu topraktan yarattı, sonra ona “Ol” dedi, o da oluverdi»."),
"prophets_154": ("Kur'an hangi peygamber için «çok doğru bir kimseydi ve onu yüce bir makama yükselttik» der?", ["İdris", "İlyas", "Zülkifl", "Elyesa"], "«Kitapta İdris'i de an: o çok doğru bir kimse, bir peygamberdi; biz onu yüce bir makama yükselttik»."),
"prophets_155": ("Nuh, halkı gemiye binerken ne dedi?", ["«Onun yüzüp gitmesi de durması da Allah'ın adıyladır»", "«Denizden korkmayın»", "«Azığınızı alın»", "«Geceyi bekleyin»"], "«Haydi binin ona: onun yüzüp gitmesi de durması da Allah'ın adıyladır»."),
"prophets_156": ("Nuh suresinde Nuh peygamber, kâfirler hakkında Rabbinden ne istedi?", ["Yeryüzünde onlardan hiç kimseyi bırakmamasını", "Onları zengin etmesini", "Onlara bir yıl daha vermesini", "Onları sürgün etmesini"], "«Rabbim! Yeryüzünde kâfirlerden tek kişi bırakma»."),
"prophets_157": ("Nuh gemiye her türden kaç tane almalıydı?", ["Birer çift", "Üçer", "Onar", "Birer tane"], "Allah ona her türden birer çift ile ailesini gemiye yüklemesini emretti."),
"prophets_158": ("Hud, Âd kavmine Allah'ın kendilerini hangi kavimden sonra halifeler kıldığını hatırlattı?", ["Nuh kavminden sonra", "Lut kavminden sonra", "Musa kavminden sonra", "Sebe halkından sonra"], "«Hatırlayın ki O sizi Nuh kavminden sonra halifeler yaptı ve yaratılışta sizi güçlü kıldı»."),
"prophets_159": ("Hakka suresine göre Âd kavmi neyle helâk edildi?", ["Dondurucu ve uğultulu bir rüzgârla", "Tufanla", "Depremle", "Çekirge sürüsüyle"], "«Âd kavmine gelince, onlar da uğultulu ve dondurucu bir rüzgârla helâk edildiler»."),
"prophets_160": ("Hud, her yüksek yere bina diken kavmini ne ile kınadı?", ["Boş yere bina dikip ebedî kalacaklarını sanmakla", "Toprağı ekmekle", "Uzak ticaretle", "Geceleri yolculukla"], "«Her yüksek yere bir alâmet dikip boş şeylerle mi uğraşıyorsunuz? Ebedî kalacakmış gibi köşkler mi ediniyorsunuz?»"),
"prophets_161": ("Kur'an'a göre Semûd kavmi dağlarla ne yapıyordu?", ["Onlardan evler yontuyorlardı", "İçlerine altın saklıyorlardı", "Üzerlerinde sürü otlatıyorlardı", "Onlardan kaçınıyorlardı"], "«Ovalarında köşkler ediniyor, dağlardan evler yontuyorsunuz»."),
"prophets_162": ("Kamer suresine göre deve Semûd'a ne olarak gönderildi?", ["Onlar için bir imtihan olarak", "Bir ödül olarak", "Krallarının hediyesi olarak", "Satılık bir sürü olarak"], "«Biz onlara bir imtihan olmak üzere o dişi deveyi göndereceğiz: onları gözetle ve sabret»."),
"prophets_163": ("Semûd kavmini deveyi öldürdükten sonra ne yakaladı?", ["Sarsıntı (er-recfe)", "Tufan", "Dondurucu rüzgâr", "Kıtlık"], "«Derken onları o sarsıntı yakaladı ve yurtlarında diz üstü çöke kaldılar»."),
"prophets_164": ("Büyük çirkinliği işleyen kavme gönderilip «Allah'tan korkmaz mısınız?» diyen peygamber kimdir?", ["Lut", "Salih", "Hud", "Şuayb"], "«Kardeşleri Lut onlara: “Allah'tan korkmaz mısınız?” demişti»."),
"prophets_165": ("Azap gecesinde Lut'a ne emredildi?", ["Ailesiyle gece yola çıkması ve kimsenin arkasına bakmaması", "Kavmini toplaması", "Şafağı beklemesi", "Dağa saklanması"], "«Gecenin bir kısmında ailenle yola çık ve içinizden hiç kimse arkasına bakmasın»."),
"prophets_166": ("Ölçü ve tartıda hile yapan Medyen halkına hangi peygamber gönderildi?", ["Şuayb", "Lut", "Hud", "İlyas"], "Şuayb onlara ölçüyü tam yapmalarını, tartıyı doğru tutmalarını ve yeryüzünde bozgunculuk yapmamalarını emretti."),
"prophets_167": ("Şuayb kavmine gerçekte ne istediğini nasıl anlattı?", ["«Ben yalnızca gücüm yettiğince ıslah etmek istiyorum»", "«Sadece servet istiyorum»", "«Hükmetmek istiyorum»", "«Gitmek istiyorum»"], "«Ben sadece gücümün yettiğince ıslah etmek istiyorum. Başarım ancak Allah'ın yardımıyladır»."),
"prophets_168": ("Allah, İbrahim'i yerine getirdiği emirlerle sınadıktan sonra ona ne dedi?", ["«Seni insanlara önder (imam) yapacağım»", "«Sana bir krallık vereceğim»", "«Seni zengin edeceğim»", "«Seni Babil kralı yapacağım»"], "«Seni insanlara önder yapacağım». İbrahim: «Soyumdan da mı?» diye sordu."),
"prophets_169": ("İbrahim, dirilttiğini ve öldürdüğünü iddia eden kralı nasıl susturdu?", ["«Allah güneşi doğudan getiriyor; haydi sen batıdan getir»", "«Yağmur yağdır»", "«Şu dağı yerinden oynat»", "«Yıldızları say»"], "«Allah güneşi doğudan getiriyor; haydi sen de onu batıdan getir». Bunun üzerine kâfir şaşırıp kaldı."),
"prophets_170": ("İbrahim'e Kâbe hakkında insanlara neyi ilan etmesi emredildi?", ["Hacı olmalarını: yaya ve her türlü binekle geleceklerdir", "Ticareti", "Savaşı", "Sessizliği"], "«İnsanlar arasında haccı ilan et: yaya olarak ve her uzak yoldan gelen yorgun develer üstünde sana gelsinler»."),
"prophets_171": ("İbrahim, dokunmayan değerli misafirlerine ne ikram etti?", ["Kızartılmış besili bir buzağı", "Ekmek ve su", "Hurma", "Süt"], "Ailesine gidip besili bir buzağı getirdi; ellerini ona uzatmadıklarını görünce içine bir korku düştü."),
"prophets_172": ("Kur'an, beraberindekilerle birlikte müminler için «güzel bir örnek» (üsve-i hasene) olduğunu kimin için söyler?", ["İbrahim", "Nuh", "Musa", "Davud"], "«İbrahim'de ve onunla beraber olanlarda sizin için güzel bir örnek vardır»."),
"prophets_173": ("İbrahim suresinde İbrahim, Mekke şehri için ne istedi?", ["Güvenli olmasını, kendisini ve oğullarını putlara tapmaktan uzak tutmasını", "Büyük bir pazar olmasını", "Saraylara sahip olmasını", "Boş kalmasını"], "«Rabbim! Bu şehri güvenli kıl; beni ve oğullarımı putlara tapmaktan uzak tut»."),
"prophets_174": ("İbrahim kavmini terk ederken ne dedi?", ["«Ben Rabbime gidiyorum: O bana yol gösterecek»", "«Servet aramaya gidiyorum»", "«Onlarla savaşmaya döneceğim»", "«Mısır'a gidiyorum»"], "«Ben Rabbime gidiyorum: O bana doğru yolu gösterecek»."),
"prophets_175": ("Kur'an hangi peygamber için «sözünde duran» ve ailesine namazı ve zekâtı emreden der?", ["İsmail", "İshak", "Yakub", "Yusuf"], "«O, sözünde duran biriydi; bir resul, bir nebiydi. Ailesine namazı ve zekâtı emrederdi»."),
"prophets_176": ("Yakub, rüyasından sonra Yusuf'a ne öğüt verdi?", ["Rüyasını kardeşlerine anlatmamasını", "Herkese anlatmasını", "Yazmasını", "Unutmasını"], "«Yavrucuğum! Rüyanı kardeşlerine anlatma, sonra sana bir tuzak kurarlar»."),
"prophets_177": ("Yusuf'un masumiyetini ev sahibinin önünde ne ispatladı?", ["Gömleğinin arkadan yırtılmış olması", "Gizli bir şahit", "Bir mektup", "Bir yemin"], "Gömlek arkadan yırtılmışsa kadın yalan söylemiştir ve o doğru söyleyenlerdendir."),
"prophets_178": ("Şehrin kadınları Yusuf'u görünce ne yaptılar?", ["Hayranlıkla ellerini kestiler", "Kaçtılar", "Sustular", "Güldüler"], "«Kadınlar onu görünce hayran kaldılar ve ellerini kestiler: “Hâşâ! Bu bir insan değil, ancak değerli bir melektir” dediler»."),
"prophets_179": ("Yusuf, rüyalarını yorumlamadan önce iki zindan arkadaşına ne öğretti?", ["Allah'ın birliğini ve hükmün yalnız O'na ait olduğunu", "Tıbbı", "Hasat hesabını", "Şiiri"], "«Ayrı ayrı rabler mi hayırlı, yoksa gücüne karşı durulamaz olan bir tek Allah mı? … Hüküm yalnızca Allah'ındır»."),
"prophets_180": ("Mısır kralı, Yusuf'la konuştuktan sonra ona ne dedi?", ["«Bugün sen yanımızda mevki sahibi ve güvenilir birisin»", "«Zindana dön»", "«Mısır'dan çık»", "«Kızımı sana veriyorum»"], "«Onunla konuşunca: “Bugün sen yanımızda mevki sahibi ve güvenilir birisin” dedi»."),
"prophets_181": ("Yusuf kardeşini yanında nasıl alıkoydu?", ["Kralın su kabı kardeşinin yükünde bulundu", "Onu satın aldı", "Sebepsiz hapsetti", "Onu vezir yaptı"], "«İşte biz Yusuf'a böyle bir tedbir öğrettik»: su kabı kardeşinin yükünden çıkarıldı."),
"prophets_182": ("Kardeşleri suçlarını itiraf edince Yusuf onlara ne dedi?", ["«Bugün size kınama yok»", "«Cezalandırılacaksınız»", "«Gidin ve bir daha gelmeyin»", "«Sizi unuttum»"], "«Bugün size kınama yok. Allah sizi bağışlasın: O merhametlilerin en merhametlisidir»."),
"prophets_183": ("Yakub oğullarına ümitsizlik hakkında ne dedi?", ["«Allah'ın rahmetinden ümit kesmeyin»", "«Bir daha yola çıkmayın»", "«Kimseyle konuşmayın»", "«Hiçbir şey yazmayın»"], "«Allah'ın rahmetinden ümit kesmeyin: Allah'ın rahmetinden ancak kâfirler ümit keser»."),
"prophets_184": ("Yusuf kıssasının sonunda hangi duayı etti?", ["Müslüman olarak ölmeyi ve salihlere katılmayı", "Bütün Mısır'a hükmetmeyi", "Kenan'a dönmeyi", "Uzun yaşamayı"], "«Canımı müslüman olarak al ve beni salihlere kat»."),
"prophets_185": ("Eyyub imtihanda Rabbine nasıl seslendi?", ["«Bana bir dert dokundu; Sen merhametlilerin en merhametlisisin»", "«Neden ben?»", "«Malımı geri ver»", "«Düşmanlarımı yok et»"], "«Kulumuz Eyyub'u da an: Rabbine seslenmiş: “Şeytan bana bir yorgunluk ve azap dokundurdu” demişti»."),
"prophets_186": ("Sad suresine göre Allah imtihandan sonra Eyyub'a neyi geri verdi?", ["Ailesini ve onlarla birlikte bir mislini daha", "Bir krallık", "Bir gemi", "Bir deve sürüsü"], "«Ona ailesini ve onlarla birlikte bir mislini daha bahşettik: bizden bir rahmet ve akıl sahipleri için bir öğüt olarak»."),
"prophets_187": ("Saffat suresine göre Yunus'u balığın karnında kalmaktan ne kurtardı?", ["Allah'ı tesbih edenlerden olması", "Gücü", "Geçen bir gemi", "Uygun bir rüzgâr"], "«Eğer tesbih edenlerden olmasaydı, diriltilecekleri güne kadar onun karnında kalırdı»."),
"prophets_188": ("Kur'an'a göre hangi kavim azap gelmeden önce iman etti ve imanı kendisine fayda verdi?", ["Yunus kavmi", "Nuh kavmi", "Lut kavmi", "Hud kavmi"], "«Keşke iman edip de imanı kendisine fayda veren bir memleket olsaydı! Yunus'un kavmi hariç»."),
"prophets_189": ("Peygambere ﷺ acelecilikte onun gibi olmaması emredilirken Kur'an Yunus'u nasıl anar?", ["«Balık sahibi» (sâhibü'l-hût)", "«Asa sahibi»", "«Dağ adamı»", "«Kuyu adamı»"], "«Balık sahibi gibi olma: hani o, üzüntüyle dolu olarak seslenmişti»."),
"prophets_190": ("Hangi peygamber kavmini Ba'l'e tapıp yaratıcıların en güzelini bırakmakla kınadı?", ["İlyas", "Elyesa", "Yunus", "Şuayb"], "«İlyas da şüphesiz peygamberlerdendi… “Ba'l'e mi tapıyorsunuz ve yaratıcıların en güzelini mi bırakıyorsunuz?”»"),
"prophets_191": ("İsmail ve İdris ile birlikte Kur'an, Allah'ın rahmetine soktuğu sabırlılar arasında hangi peygamberi anar?", ["Zülkifl", "İlyas", "Yunus", "Elyesa"], "«İsmail, İdris ve Zülkifl: hepsi sabredenlerdendi. Onları rahmetimize soktuk»."),
"prophets_192": ("Firavun kovalarken Allah İsrailoğulları için denizde ne yaptı?", ["Denizi yardı ve onları kurtardı", "Geceyi indirdi", "Gemiler gönderdi", "Denizi sonsuza dek kuruttu"], "«Sizin için denizi yardığımızı hatırlayın: sizi kurtardık ve Firavun ailesini boğduk»."),
"prophets_193": ("Musa neden Allah'tan Harun'u kendisiyle göndermesini istedi?", ["Çünkü o kendisinden daha güzel konuşuyordu", "Çünkü daha yaşlıydı", "Çünkü Mısır'ı biliyordu", "Çünkü yazı yazabiliyordu"], "«Kardeşim Harun'un dili benimkinden daha düzgündür: onu beni doğrulayan bir yardımcı olarak benimle gönder»."),
"prophets_194": ("Musa ve Harun Firavun'a nasıl konuşmalıydı?", ["Yumuşak sözle", "Tehditle", "Ona bakmadan", "Sadece yazıyla"], "«Ona yumuşak söz söyleyin: belki öğüt alır veya korkar»."),
"prophets_195": ("Firavun ailesinden kim imanını gizleyerek Musa'yı savundu?", ["Firavun ailesinden mümin bir adam", "Baş kâhin", "Ordu komutanı", "Vezir Haman"], "«Firavun ailesinden, imanını gizleyen mümin bir adam dedi ki: “Rabbim Allah'tır dediği için bir adamı öldürecek misiniz?”»"),
"prophets_196": ("Musa'nın yokluğunda Harun kavmine ne dedi?", ["Buzağı ile imtihan edildiklerini ve kendisine uymaları gerektiğini", "Buzağıyı saklamalarını", "Mısır'a gitmelerini", "Susmalarını"], "«Ey kavmim! Siz bununla yalnızca imtihan edildiniz. Rabbiniz Rahman'dır: bana uyun»."),
"prophets_197": ("Firavun'un karısı bebek Musa'yı bulunca ne dedi?", ["«Benim ve senin için göz aydınlığı olacak: onu öldürmeyin»", "«Onu annesine geri verin»", "«Onu nehre götürün»", "«Onu satın»"], "«Firavun'un karısı dedi ki: “Benim ve senin için göz aydınlığı. Onu öldürmeyin: belki bize faydası olur”»."),
"prophets_198": ("Musa, bilgin kula (Hızır'a) uymayı nasıl istedi?", ["«Sana tâbi olabilir miyim, bana öğretmen şartıyla?»", "«Bana emret, itaat edeyim»", "«Ücret karşılığı öğret»", "«Benimle gel»"], "«Sana öğretilen doğruluktan bana da öğretmen için sana tâbi olabilir miyim?»"),
"prophets_199": ("Musa buzağıyı gördükten sonra kavmine nasıl döndü?", ["Öfkeli ve üzgün olarak", "Sevinçli olarak", "Sessiz olarak", "İlgisiz olarak"], "«Musa kavmine öfkeli ve üzgün olarak döndüğünde… levhaları bıraktı»."),
"prophets_200": ("Nâziat suresine göre Musa Firavun'a hangi mesajı götürecekti?", ["«Arınmak ister misin, seni Rabbine yönelteyim mi?»", "«Kavmimi bana geri ver»", "«Bana bir saray yap»", "«Mısır'dan çık»"], "«Firavun'a git: o azdı. De ki: arınmak ister misin? Seni Rabbine yönelteyim de O'ndan korkasın»."),
"prophets_201": ("Akşam ve sabah Davud ile birlikte Allah'ı kim tesbih ediyordu?", ["Dağlar ve kuşlar", "Nehirler", "Yıldızlar", "Rüzgârlar"], "«Dağları onunla birlikte akşam ve kuşluk vakti tesbih etsinler diye emrimize boyun eğdirdik; toplanıp gelen kuşları da»."),
"prophets_202": ("Kur'an'a göre Allah, sağlam bir mülkün yanında Davud'a ne verdi?", ["Hikmeti ve kesin hükmü", "Büyük ordular", "Altın ve gümüş", "Fildişi bir saray"], "«Onun mülkünü güçlendirdik; ona hikmet ve açık, kesin konuşma yeteneği verdik»."),
"prophets_203": ("Davud'a zırh yaparken ne emredildi?", ["Halkaları ölçülü yapmasını", "Adını kazımasını", "Onları altınla kaplamasını", "Onları satmasını"], "«Geniş zırhlar yap ve dokumasını ölçülü tut»."),
"prophets_204": ("Allah kendilerine ilim verince Davud ve Süleyman ne dedi?", ["«Bizi mümin kullarının birçoğuna üstün kılan Allah'a hamdolsun»", "«En üstün biziz»", "«Bizim dengimiz yok»", "«Bunu hak ettik»"], "«Bizi mümin kullarının birçoğuna üstün kılan Allah'a hamdolsun»."),
"prophets_205": ("Süleyman, karıncanın kavmini uyardığını duyunca ne yaptı?", ["Gülümsedi ve Allah'tan şükreden olmayı diledi", "Öfkelendi", "Ordusunu sessizce çevirdi", "Susmalarını emretti"], "«Onun sözüne gülümsedi ve dedi ki: “Rabbim! Nimetine şükretmemi bana ilham et”»."),
"prophets_206": ("Hüdhüd Süleyman'a hangi haberi getirdi?", ["Sebe'de bir kadının hüküm sürdüğünü ve halkının güneşe secde ettiğini", "Bir ordunun yaklaştığını", "Kuraklık olduğunu", "Gizli bir hazine bulunduğunu"], "«Sebe'den sana kesin bir haber getirdim: orada onlara hükmeden bir kadın buldum… güneşe secde ediyorlar»."),
"prophets_207": ("Sebe melikesini Süleyman'ın sarayına girerken ne şaşırttı?", ["Su sandığı cam zemin", "Ehlileştirilmiş bir aslan", "Asma bahçe", "Altın bir taht"], "«Ona: “Saraya gir” denildi. Onu görünce derin bir su sandı ve bacaklarını açtı. Süleyman: “Bu, camdan yapılmış saraydır” dedi»."),
"prophets_208": ("Kur'an'a göre Süleyman'ın orduları kimlerden oluşuyordu?", ["Cinlerden, insanlardan ve kuşlardan", "Sadece süvarilerden", "Denizcilerden", "Sadece okçulardan"], "«Süleyman'ın cinlerden, insanlardan ve kuşlardan orduları toplandı ve düzenli olarak sevk edildi»."),
"prophets_209": ("Zekeriyya Rabbine seslenirken durumunu nasıl anlattı?", ["«Kemiklerim zayıfladı ve başım ağarmış saçlarla tutuştu»", "«Zenginim ve doydum»", "«Kavmimden uzağım»", "«Yolculuktayım»"], "«Rabbim! Kemiklerim zayıfladı, başım ağarmış saçlarla tutuştu; sana dua etmekle hiçbir zaman bedbaht olmadım»."),
"prophets_210": ("Yahya'nın doğumu için Zekeriyya'ya hangi işaret verildi?", ["Üç gün insanlarla ancak işaretle konuşabilmesi", "Bir yıldız", "Mevsimsiz bir yağmur", "Tekrarlanan bir rüya"], "«Senin işaretin, üç gün insanlarla işaretten başka türlü konuşamamandır»."),
"prophets_211": ("Yahya'ya Kitap hakkında ne denildi?", ["«Kitaba kuvvetle sarıl»", "«Kitabı sakla»", "«Kitabı kopyala»", "«Onu bir kez oku»"], "«Ey Yahya! Kitaba kuvvetle sarıl!» Ve ona daha çocukken hikmet verdik."),
"prophets_212": ("Melekler Meryem'e seçildiğini bildirdikten sonra ona ne emretti?", ["Rabbine gönülden boyun eğmesini, secde ve rükû etmesini", "Yolculuğa çıkmasını", "Sonsuza dek susmasını", "Mabette öğretmesini"], "«Ey Meryem! Rabbine gönülden boyun eğ, secde et ve rükû edenlerle birlikte rükû et»."),
"prophets_213": ("Doğum sırasında Meryem'e yemek için neyi sallaması söylendi?", ["Hurma ağacının gövdesini, taze hurma dökülsün diye", "Bir zeytin ağacını", "Bir incir ağacını", "Bir asmayı"], "«Hurma ağacının gövdesini kendine doğru silkele: üzerine taze, olgun hurma dökülsün»."),
"prophets_214": ("İsa beşikte Allah'ın kendisine neyi tavsiye ettiğini söyledi?", ["Yaşadığı sürece namazı ve zekâtı", "Ticareti", "Susmayı", "Yolculuğu"], "«Yaşadığım sürece bana namazı ve zekâtı emretti»."),
"prophets_215": ("Zuhruf suresi Meryem oğlu İsa'yı nasıl anlatır?", ["Allah'ın nimet verdiği ve İsrailoğullarına örnek kıldığı bir kul", "İsrail kralı", "İnen bir melek", "Mabet kâtibi"], "«O, sadece kendisine nimet verdiğimiz ve İsrailoğullarına örnek kıldığımız bir kuldur»."),
"prophets_216": ("Kıyamet günü Allah sorunca İsa ne cevap verecek?", ["«Seni tenzih ederim! Hakkım olmayanı söylemek bana yakışmaz»", "«Hatırlamıyorum»", "«Onlar yazdı»", "«Havarilere sor»"], "«Seni tenzih ederim! Hakkım olmayan bir şeyi söylemek bana yakışmaz»."),
"prophets_217": ("Kur'an Meryem oğlu İsa'yı nasıl tarif eder?", ["Allah'ın elçisi, Meryem'e ulaştırdığı kelimesi ve O'ndan bir ruh", "Gönderilmiş bir melek", "Adil bir kral", "Bilgin bir kâtip"], "«Meryem oğlu İsa Mesih, ancak Allah'ın elçisi, Meryem'e ulaştırdığı kelimesi ve O'ndan bir ruhtur»."),
"prophets_218": ("Duha suresinde Allah, Peygamberine ﷺ hangi nimetleri hatırlatır?", ["Onu yetim bulup barındırdı, yolunu bulmasını sağladı ve zengin etti", "Ona bir krallık verdi", "Ona bir ordu verdi", "Ona bir saray verdi"], "«O seni yetim bulup barındırmadı mı? Şaşırmış bulup yol göstermedi mi? Fakir bulup zengin etmedi mi?»"),
"prophets_219": ("İnşirah suresi hangi vaadi iki kez tekrarlar?", ["«Zorlukla beraber kolaylık vardır»", "«Zafer yakındır»", "«Cennet vadedilmiştir»", "«Düşmanlar helâk olacak»"], "«Şüphesiz zorlukla beraber bir kolaylık vardır. Gerçekten zorlukla beraber bir kolaylık vardır»."),
"prophets_220": ("Kevser suresinde Peygambere ﷺ ne verildi ve karşılığında ne emredildi?", ["Kevser; Rabbine namaz kılması ve kurban kesmesi", "Ordu; savaşması", "Krallık; yönetmesi", "Hazine; dağıtması"], "«Biz sana Kevser'i verdik. O halde Rabbin için namaz kıl ve kurban kes»."),
"prophets_221": ("Tevbe suresi Elçiyi ﷺ müminlere karşı nasıl anlatır?", ["Onlara düşkün, şefkatli ve merhametli", "Sert ve uzak", "Zengin ve güçlü", "Suskun ve inzivada"], "«Andolsun size kendinizden bir peygamber gelmiştir… size düşkün, müminlere karşı şefkatli ve merhametlidir»."),
"prophets_222": ("Kur'an'a göre öyle olsaydı, insanları Peygamberden ﷺ ne uzaklaştırırdı?", ["Kaba ve katı yürekli olsaydı", "Zengin olsaydı", "Genç olsaydı", "Suskun olsaydı"], "«Allah'ın rahmeti sayesinde onlara yumuşak davrandın. Eğer kaba ve katı yürekli olsaydın, çevrenden dağılıp giderlerdi»."),
"prophets_223": ("Allah'ı ve ahiret gününü umanlar için Kur'an, Allah'ın Elçisi ﷺ hakkında ne der?", ["Onlar için güzel bir örnektir", "O bir kraldır", "O bir hâkimdir", "O bir kervan kılavuzudur"], "«Andolsun, Allah'ın Elçisinde sizin için, Allah'ı ve ahiret gününü umanlar için güzel bir örnek vardır»."),
"prophets_224": ("Sebe suresine göre Peygamber Muhammed ﷺ kime gönderildi?", ["Bütün insanlığa", "Sadece Kureyş'e", "Sadece Araplara", "Medine halkına"], "«Biz seni ancak bütün insanlara müjdeleyici ve uyarıcı olarak gönderdik»."),
"prophets_225": ("Kâbe çevresindeki putlar kaldırılırken Peygamber ﷺ hangi ayeti okudu?", ["«Hak geldi, batıl yok oldu»", "«Sana apaçık bir fetih verdik»", "«De ki: O Allah birdir»", "«Allah'ın yardımı gelince»"], "«De ki: Hak geldi, batıl yok oldu; şüphesiz batıl yok olmaya mahkûmdur»."),
"prophets_226": ("Bakara suresinin sonunda müminler Allah'ın elçileri hakkında ne der?", ["«O'nun elçilerinden hiçbiri arasında ayırım yapmayız»", "«Sadece sonuncusuna uyarız»", "«Birini tercih ederiz»", "«Onları görmezden geliriz»"], "«O'nun elçilerinden hiçbiri arasında ayırım yapmayız. Ve dediler ki: işittik ve itaat ettik»."),
"prophets_227": ("Her elçi kavmine hangi ortak mesajı götürdü?", ["«Allah'a kulluk edin ve tağuttan kaçının»", "«Mabetler yapın»", "«Zenginleşin»", "«Kitaplar yazın»"], "«Andolsun biz her ümmete bir peygamber gönderdik: Allah'a kulluk edin ve tağuttan kaçının»."),
"prophets_228": ("İbrahim suresine göre her elçi hangi dille gönderildi?", ["Kendi kavminin diliyle, onlara açıklasın diye", "Sadece Arapça", "İbranice", "Semavi bir dille"], "«Biz her peygamberi ancak kendi kavminin diliyle gönderdik ki onlara açıklasın»."),
"prophets_229": ("Enbiya suresine göre Muhammed'den ﷺ önceki her elçiye ne vahyedildi?", ["O'ndan başka ilah olmadığı: öyleyse O'na kulluk edin", "Bir mabet inşa etmeleri", "Ülkeler fethetmeleri", "Sır saklamaları"], "«Senden önce hiçbir peygamber göndermedik ki ona: “Benden başka ilah yoktur, öyleyse bana kulluk edin” diye vahyetmiş olmayalım»."),
"prophets_230": ("Enam suresinde İbrahim'in hidayete erdirilmiş soyu olarak hangi peygamber topluluğu sayılır?", ["Davud, Süleyman, Eyyub, Yusuf, Musa ve Harun başta olmak üzere", "Sadece Musa ve İsa", "Sadece İsmail ve İshak", "Sadece Nuh ve Hud"], "Bu bölüm, Allah'ın hidayete erdirdiği uzun bir peygamber silsilesini sayar ve şöyle der: «İyilik yapanları böyle mükâfatlandırırız»."),
"prophets_231": ("Kur'an elçilerin birbirine göre durumu hakkında ne der?", ["Allah bazılarını bazılarına üstün kıldı", "Hepsi aynı derecededir", "Sadece sonuncusu geçerlidir", "Birbirlerini bilmiyorlardı"], "«İşte o peygamberler: biz onların bir kısmını bir kısmına üstün kıldık»."),
"prophets_232": ("Âl-i İmran suresine göre Allah peygamberlerden hangi sözü aldı?", ["Yanlarındakini doğrulayarak gelecek Elçiye iman edip ona yardım etmeleri", "Kavimlerini asla terk etmemeleri", "Her birinin bir mabet yapması", "Her birinin bir kitap yazması"], "«Size, yanınızdakini doğrulayan bir Elçi geldiğinde ona mutlaka iman edecek ve ona yardım edeceksiniz»."),
"prophets_233": ("Allah'ın aynı dini kendilerine şeriat kıldığını söylerken Kur'an hangi peygamberleri anar?", ["Nuh, İbrahim, Musa ve İsa'yı, Peygambere ﷺ vahyedilenle birlikte", "Sadece Âdem ve İdris'i", "Sadece Davud ve Süleyman'ı", "Sadece Hud ve Salih'i"], "«Nuh'a tavsiye ettiğini, sana vahyettiğimizi ve İbrahim'e, Musa'ya ve İsa'ya tavsiye ettiğimizi size de din olarak şeriat kıldı»."),
"prophets_234": ("Kur'an kıssasını anlatmadığı elçiler hakkında ne der?", ["Allah'ın Peygambere ﷺ kıssasını anlatmadığı elçiler vardır", "Onlar yoktur", "Hepsi adıyla anılmıştır", "Önemleri yoktur"], "«Onlardan sana kıssasını anlattıklarımız da var, anlatmadıklarımız da»."),
"prophets_235": ("Yusuf suresine göre Allah bütün elçilerini kimlerden seçti?", ["Şehir halkından, kendilerine vahyettiği erkeklerden", "Meleklerden", "Krallardan", "Sadece çöl halkından"], "«Senden önce de şehirler halkından kendilerine vahyettiğimiz erkeklerden başkasını göndermedik»."),
"prophets_236": ("Kur'an, Muhammed'den ﷺ önce yalanlanan elçiler hakkında neyi hatırlatır?", ["Yardımımız gelinceye kadar sabrettiler", "Vazgeçtiler", "Saklandılar", "Mesajlarını değiştirdiler"], "«Andolsun senden önce de peygamberler yalanlandı; kendilerine yardımımız gelinceye kadar yalanlanmalarına sabrettiler»."),
"prophets_237": ("Âl-i İmran suresine göre Allah âlemlere hangi aileleri seçti?", ["Âdem'i, Nuh'u, İbrahim ailesini ve İmran ailesini", "Mısır krallarını", "Medine kabilelerini", "Sebe halkını"], "«Allah Âdem'i, Nuh'u, İbrahim ailesini ve İmran ailesini âlemlere üstün kıldı»."),
"prophets_238": ("Musa, kavmini Kutsal Toprağa girmeye çağırırken hangi nimetleri hatırlattı?", ["Allah'ın aralarından peygamberler çıkardığını ve onları krallar yaptığını", "Onlara gemiler verdiğini", "Onlara altın verdiğini", "Onlara at verdiğini"], "«Ey kavmim! Allah'ın üzerinizdeki nimetini hatırlayın: içinizden peygamberler çıkardı ve sizi krallar yaptı»."),
"prophets_239": ("Kur'an'a göre Tevrat ve İncil ümmî Peygamberi nasıl tarif ediyordu?", ["İyiliği emreder, kötülüğü yasaklar ve yüklerini hafifletir", "Servet getirir", "Zorla hükmeder", "Mabetler yapar"], "«…yanlarındaki Tevrat ve İncil'de yazılı buldukları ümmî peygamber: onlara iyiliği emreder, kötülüğü yasaklar… ve üzerlerindeki ağır yükleri kaldırır»."),
"prophets_240": ("Nuh, kavmine tuzak kurmaları için meydan okurken kime dayandığını söyledi?", ["Allah'a: O'na tevekkül etti", "Oğullarına", "Kabilesine", "Gemisine"], "«Ben Allah'a tevekkül ettim. Siz de ortaklarınızla toplanıp işinizi kararlaştırın»."),
"prophets_241": ("İbrahim duasında hastalandığında şifayı kime nispet eder?", ["Yalnız Allah'a", "Hekimlere", "Bitkilere", "Zamana"], "«Hastalandığımda bana şifa veren O'dur», dedi İbrahim Rabbini anlatırken."),
"prophets_242": ("Saffat suresine göre İbrahim'in oğlu ne ile fidye verildi?", ["Büyük bir kurbanla", "Altından bir fidyeyle", "Bir kervanla", "Bütün bir sürüyle"], "«Ona büyük bir kurbanlık fidye verdik»."),
"prophets_243": ("«Deyin ki: Allah'a iman ettik…» ayetinde müminler neye iman ettiklerini bildirir?", ["İbrahim'e, İsmail'e, İshak'a, Yakub'a, Musa'ya, İsa'ya ve peygamberlere indirilene", "Tek bir kitaba", "Tek bir peygambere", "Kendi geleneklerine"], "«Deyin ki: Allah'a, bize indirilene, İbrahim'e, İsmail'e, İshak'a, Yakub'a indirilene iman ettik…»"),
"prophets_244": ("Allah, elçilerin haberlerini Peygambere ﷺ neden anlatır?", ["Kalbini pekiştirmek için", "Onu meşgul etmek için", "Ona tarih öğretmek için", "Onu eğlendirmek için"], "«Peygamberlerin haberlerinden sana anlattığımız her şey, kalbini pekiştirmek içindir»."),
"prophets_245": ("Kehf suresinin sonunda Peygambere ﷺ kendisi hakkında ne demesi emredildi?", ["«Ben de ancak sizin gibi bir insanım; bana ilahınızın tek bir ilah olduğu vahyediliyor»", "«Ben bir kralım»", "«Ben bir meleğim»", "«Gaybı bilirim»"], "«De ki: Ben de ancak sizin gibi bir insanım; bana ilahınızın tek bir ilah olduğu vahyediliyor»."),
"prophets_246": ("Fetih suresi Elçi ﷺ ile birlikte olanları nasıl anlatır?", ["Kâfirlere karşı sert, kendi aralarında merhametli", "Zengin ve kalabalık", "Suskun ve inzivada", "Yolcu ve tüccar"], "«Muhammed Allah'ın elçisidir. Onunla beraber olanlar kâfirlere karşı sert, kendi aralarında merhametlidirler»."),
"prophets_247": ("Necm suresi Peygamberin ﷺ sözü hakkında ne der?", ["O hevadan konuşmaz: o ancak vahyedilen bir vahiydir", "Şair gibi konuşur", "Kâhin gibi konuşur", "Kendiliğinden konuşur"], "«Arkadaşınız sapmadı ve azmadı; o hevadan konuşmaz. O ancak kendisine vahyedilen bir vahiydir»."),
"prophets_248": ("Allah'ın yardımı ve fetih gelince Peygambere ﷺ ne emredildi?", ["Rabbini hamd ile tesbih etmesi ve O'ndan bağışlanma dilemesi", "Ziyafet vermesi", "Anıt dikmesi", "Dinlenmesi"], "«Allah'ın yardımı ve fetih geldiğinde… Rabbini hamd ile tesbih et ve O'ndan bağışlanma dile»."),
"prophets_249": ("Cuma suresi ümmîlere gönderilen Elçiye hangi üç görevi verir?", ["Ayetleri okumak, onları arındırmak, onlara Kitabı ve hikmeti öğretmek", "İnşa etmek, ticaret yapmak ve yönetmek", "Yazmak, saymak ve seyahat etmek", "Hüküm vermek, cezalandırmak ve vergi toplamak"], "«O, ümmîler arasında kendilerinden bir elçi gönderendir: onlara ayetlerini okur, onları arındırır ve onlara Kitabı ve hikmeti öğretir»."),
"prophets_250": ("Peygamber ﷺ aralarındayken Kur'an hangi güvenceden söz eder?", ["Allah, o aralarındayken onlara azap etmeyecekti", "Zengin olacaklardı", "Her zaman kazanacaklardı", "Ölmeyeceklerdi"], "«Sen onların içindeyken Allah onlara azap edecek değildir»."),
}
